"""Generate synthesizable, full-phase CORDIC NCO (no real/$sin in RTL)."""
from pathlib import Path
import math

src=Path(__file__).resolve().parents[2]/'src'
table='\n'.join(f"                {i}: atan_turn = 50'sd{round(math.atan(2**-i)*2**48/(2*math.pi))};" for i in range(40))
gain=math.prod(1/math.sqrt(1+2**(-2*i)) for i in range(40))
initial=round(gain*131071*2**30)
rtl='''`timescale 1ns/1ps
// Generated by testbench/scoreboard/generate_nco.py. Amplitude denominator
// is 131071, matching the original MATLAB model, not 2^17.
// Combinational next-sample references let the mixer consume the new phase.
module hrg_nco (
    input wire clk, nrst, sample_en,
    input wire [31:0] fcw,
    output reg signed [17:0] cos_o, sin_o,
    output reg [31:0] phase_o,
    output reg wrap_pulse_o,
    output wire signed [17:0] cos_sample_o, sin_sample_o
);
    reg [31:0] phase_acc;
    wire [31:0] next_phase=phase_acc+fcw;
    function signed [49:0] atan_turn;
        input integer i;
        begin
            case(i)
TABLE
                default: atan_turn=0;
            endcase
        end
    endfunction
    function signed [17:0] sine;
        input [31:0] phase;
        reg signed [55:0] x,y,nx,ny;
        reg signed [49:0] z;
        reg signed [55:0] mag;
        reg [30:0] residual;
        integer k;
        begin
            residual={1'b0,phase[29:0]};
            if(phase[30]) residual=31'h40000000-residual;
            z=$signed({3'b000,residual,16'b0});
            x=56'sdINITIAL; y=0;
            for(k=0;k<40;k=k+1) begin
                if(z>=0) begin nx=x-(y>>>k);ny=y+(x>>>k);z=z-atan_turn(k);end
                else begin nx=x+(y>>>k);ny=y-(x>>>k);z=z+atan_turn(k);end
                x=nx;y=ny;
            end
            mag=(y+56'sd536870912)>>>30;
            if(mag>131071) mag=131071;
            if(mag<0) mag=0;
            sine=phase[31] ? -mag : mag;
        end
    endfunction
    assign cos_sample_o=sine(next_phase+32'h40000000);
    assign sin_sample_o=sine(next_phase);
    always @(posedge clk or negedge nrst) begin
        if(!nrst) begin phase_acc<=0;phase_o<=0;cos_o<=131071;sin_o<=0;wrap_pulse_o<=0;end
        else begin
            wrap_pulse_o<=0;
            if(sample_en) begin
                phase_acc<=next_phase;phase_o<=next_phase;
                cos_o<=cos_sample_o;sin_o<=sin_sample_o;
                wrap_pulse_o<=next_phase<phase_acc;
            end
        end
    end
endmodule
'''.replace('TABLE',table).replace('INITIAL',str(initial))
(src/'hrg_nco.v').write_text(rtl,encoding='utf-8')
